import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.apps.form.service.FormUtil;
import java.util.Arrays;

import org.joget.directory.model.service.DirectoryManager;
import org.joget.directory.model.User;
import org.joget.commons.util.LogUtil;
import java.util.*;
import org.joget.apps.app.service.AppUtil;



public FormRowSet load(Element element, String primaryKey, FormData formData) {
String departmentId = "cellule"; // Replace with your department ID
String gradeId = "agent";  // Replace with your role ID

    FormRowSet rows = new FormRowSet();

    // Add default value "--"
    FormRow defaultOption = new FormRow();
    defaultOption.setProperty(FormUtil.PROPERTY_VALUE, "");
    defaultOption.setProperty(FormUtil.PROPERTY_LABEL, "");
    rows.add(defaultOption);

    // Array of countries in French
    // Collection matchedUsers = new ArrayList();

    try {
        // Get the DirectoryManager instance
        DirectoryManager directoryManager = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");
    
        // Retrieve users based on filters
        Collection users = directoryManager.getUsers(null, "rsu", departmentId, gradeId, null, null, "1", null, false, null, null);
        // Iterate through users and collect usernames
        for (Object obj : users) {
            User user = (User) obj;
            LogUtil.info("user ---> " , user.toString());
            FormRow option = new FormRow();
            option.setProperty(FormUtil.PROPERTY_VALUE, user.getUsername());
            option.setProperty(FormUtil.PROPERTY_LABEL, user.getFirstName()+user.getLastName());
            rows.add(option);
            // matchedUsers.add(user.getUsername());
        }
    
        // return matchedUsers;
        // Log the matched users
        LogUtil.info("ProcessMapping", "Matched Users: " + rows.toString());
    
    } catch (Exception e) {
        LogUtil.error("ProcessMapping", e, e.getMessage());
    }
 

    // Add sorted countries to the rows


    return rows;
}

// Call load method with injected variables
return load(element, primaryKey, formData);
